// Oeste EmptyAttachment — Mesa theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with dark: variant, JSX transform.
// Requires Mesa tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/mesa/src/index.js
// Docs: https://oeste.hiddeninwest.com/mesa/#/components/empty-attachment

const SOFT = "text-[#5b5f65] dark:text-[#a79b82]";

const LINE = "border-[#ddd6c7] dark:border-[#2e2720]";

export function EmptyAttachment({ children }) {
  return (
    <div className={`rounded-md border-[1.5px] border-dashed ${LINE} px-[18px] py-6 text-center text-[14.5px] ${SOFT}`}>
      {children}
    </div>
  );
}
